import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.Di-jvWLj.js";const h=JSON.parse('{"title":"Multiple Replicas","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/replicas.md","filePath":"deployment/replicas.md","lastUpdated":1793384109000}'),o={name:"deployment/replicas.md"};function s(i,e,c,l,d,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="multiple-replicas" tabindex="-1">Multiple Replicas <a class="header-anchor" href="#multiple-replicas" aria-label="Permalink to &quot;Multiple Replicas&quot;">​</a></h1><p>Running more than one replica of an agent app relies on the store. Core, the TypeORM store, HTTP intake and <code>@chamvi/channel-cron</code> coordinate through that shared store.</p><h2 id="upgrading-to-untrusted-content-gates" tabindex="-1">Upgrading to untrusted-content gates <a class="header-anchor" href="#upgrading-to-untrusted-content-gates" aria-label="Permalink to &quot;Upgrading to untrusted-content gates&quot;">​</a></h2><p>This upgrade requires downtime. <strong>Do not run old and new runtimes against the same store</strong>, even temporarily during a rolling deployment.</p><ol><li>Stop <strong>all old ingress, workers and approval pollers</strong> across every replica and scheduled job. Wait for the processes to exit; draining executions alone is not sufficient.</li><li>With all old processes stopped, apply <code>RunTaint1792800000000</code> (or the equivalent custom-store migration and unfinished-run backfill).</li><li>Start <strong>only new binaries</strong> against the migrated store. Resumed legacy unfinished runs are conservatively tainted and may require outbound approval.</li></ol><p>Old approval pollers do not understand the safe notification field: they can post a new gate&#39;s private argument-bearing <code>waiting.body</code> to its source channel. Old ingress and workers can create or checkpoint untainted runs after the one-time backfill. Shared claims and notification locks do not prevent either version-compatibility problem. See <a href="/repositories/writing-a-repository#persist-run-taint">Writing a repository</a> for the persistence requirements.</p><h2 id="what-core-already-guarantees" tabindex="-1">What core already guarantees <a class="header-anchor" href="#what-core-already-guarantees" aria-label="Permalink to &quot;What core already guarantees&quot;">​</a></h2><p>With a shared, durable store such as the <a href="/repositories/typeorm">TypeORM store</a> (<code>createMemoryStore()</code> cannot be shared), several <code>Engine</code>s coordinate without a leader:</p><ul><li><strong>One executor per run.</strong> Run claims are leases (<code>claimTtlMs</code>, renewed every third of it). A replica that loses its lease stops writing.</li><li><strong>One run per concurrency key.</strong> Checked under a store lock, across replicas.</li><li><strong>Shared numerical ceilings.</strong> Agent and subscription <code>concurrencyMaxRuns</code> count running runs under an agent admission lock. Waiting approvals release numerical capacity but keep their keys. All replicas must use compatible definitions and complete admission operations inside the lock TTL. <code>CHAMVI_MAX_CONCURRENT_RUNS</code> is still local to each engine, not a fleet cap. See <a href="/guide/concurrency#shared-agent-and-subscription-ceilings">Concurrency</a>.</li><li><strong>One run per idempotency key.</strong> <code>dispatch()</code> claims the key atomically; redeliveries to any replica return the same run.</li><li><strong>Crash recovery.</strong> Every replica&#39;s poll requeues runs whose claim expired, and the next execution continues from the latest checkpoint.</li><li><strong>Graceful drain.</strong> A terminating pod marks its unfinished runs <code>interrupted</code> and another replica picks them up.</li><li><strong>Cross-replica cancel.</strong> <code>cancel()</code> on any replica reaches the run&#39;s owner on its next poll.</li><li><strong>One approval message.</strong> A store lock per approval plus the message key (<code>&lt;runId&gt;:&lt;approvalId&gt;</code>) the channel dedupes on; a tool&#39;s <code>emit()</code> is recorded as an effect, so a redone step sends once.</li><li><strong>Cron once per tick.</strong> The cron channel (<a href="/guide/scheduler"><code>@chamvi/channel-cron</code></a>) takes a store lock per subscription and scheduled time (never released, so a late replica cannot fire the same tick again) and dispatches with an idempotency key built from the same pair. <code>engine.drain()</code> stops it before draining the runs.</li></ul><p>Give each replica a distinct <code>owner</code> (the default <code>&lt;hostname&gt;-&lt;pid&gt;</code> already is in Kubernetes). See <a href="/guide/concurrency">Concurrency, Leases &amp; Multi-Replica</a>.</p><h2 id="webhooks-and-deployment" tabindex="-1">Webhooks and deployment <a class="header-anchor" href="#webhooks-and-deployment" aria-label="Permalink to &quot;Webhooks and deployment&quot;">​</a></h2><p>The HTTP app can accept deliveries on any replica. GitHub uses the delivery id as its default idempotency key, so a redelivery to another replica deduplicates through the shared store. A <code>202</code> means durable acceptance, not execution completion. Excess work remains queued, without a storage bound; use <a href="/reference/http#channel-http-request-limits">channel HTTP policies</a> separately from execution ceilings.</p><p>The <a href="https://github.com/chamvi/helm" target="_blank" rel="noreferrer">Helm chart</a> defaults to one replica with the <code>Recreate</code> strategy. Raising the replica count requires a shared store and compatible definitions. Ingress settings do not configure the app&#39;s <code>trustProxy</code>; see <a href="/deployment/kubernetes#ingress-client-addresses-and-channel-bursts">Ingress client addresses</a>.</p>',13)])])}const g=t(o,[["render",s]]);export{h as __pageData,g as default};
